// Generates the coverage page (docs/SPEC.md, "Docs site": auto-generated per season):
//   - per anime season, the states the bots' pinned Season tracker issues report
//     (mapped, auto-update, awaiting review, conflict, waiting for seed, upcoming), from the
//     GitHub API (GITHUB_TOKEN raises the rate limit; without network the section says so);
//   - per premiere year, how many works have TVDB and TMDB episode mappings, from the dump
//     (COURMAP_DUMP or ../out/courmap.sqlite; without a dump the section says so).
// Output: src/content/docs/coverage.md (gitignored).
import { existsSync } from 'node:fs';
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const site = fileURLToPath(new URL('../', import.meta.url));
const out = path.join(site, 'src/content/docs/coverage.md');
const dumpPath = process.env.COURMAP_DUMP ?? path.join(site, '../out/courmap.sqlite');
const STATES = ['mapped', 'auto-update', 'awaiting review', 'conflict', 'waiting for seed', 'upcoming'];

async function seasons() {
  const headers = { Accept: 'application/vnd.github+json', ...(process.env.GITHUB_TOKEN && { Authorization: `Bearer ${process.env.GITHUB_TOKEN}` }) };
  try {
    const res = await fetch('https://api.github.com/repos/courmap/courmap/issues?labels=season-tracker&state=open&per_page=20', { headers, signal: AbortSignal.timeout(15_000) });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const issues = await res.json();
    const rows = issues
      .map((i) => {
        const season = i.title.replace(/^Season tracker:\s*/, '');
        const counts = Object.fromEntries(STATES.map((s) => [s, Number(new RegExp(`(\\d+) ${s}\\b`).exec(i.body ?? '')?.[1] ?? 0)]));
        const total = Object.values(counts).reduce((a, b) => a + b, 0);
        return { season, url: i.html_url, counts, total, updated: i.updated_at };
      })
      .sort((a, b) => (a.updated < b.updated ? 1 : -1));
    if (rows.length === 0) return ['No Season tracker issue is open yet.'];
    return [
      `| Season | Shows | ${STATES.map((s) => s[0].toUpperCase() + s.slice(1)).join(' | ')} |`,
      `| --- | --- | ${STATES.map(() => '---').join(' | ')} |`,
      ...rows.map((r) => `| [${r.season}](${r.url}) | ${r.total} | ${STATES.map((s) => r.counts[s]).join(' | ')} |`),
      '',
      `Read from the pinned Season tracker issues when this site was built (${new Date().toISOString().slice(0, 10)}).`,
    ];
  } catch (err) {
    return [`The Season tracker issues could not be read when this site was built (${err.message}). See [the issues labeled season-tracker](https://github.com/courmap/courmap/issues?q=label%3Aseason-tracker).`];
  }
}

async function years() {
  if (!existsSync(dumpPath)) return ['No dump was available when this site was built.'];
  const { DatabaseSync } = await import('node:sqlite');
  const db = new DatabaseSync(dumpPath, { readOnly: true });
  try {
    const version = db.prepare("SELECT value FROM meta WHERE key = 'data_version'").get()?.value;
    const rows = db
      .prepare(
        `SELECT w.year AS year, COUNT(*) AS works,
           SUM(EXISTS (SELECT 1 FROM projections p WHERE p.work_id = w.id AND p.provider = 'tvdb_show')) AS tvdb,
           SUM(EXISTS (SELECT 1 FROM projections p WHERE p.work_id = w.id AND p.provider = 'tmdb_show')) AS tmdb
         FROM works w WHERE w.type IN ('tv', 'ona', 'ova') AND w.year IS NOT NULL GROUP BY w.year ORDER BY w.year DESC LIMIT 12`,
      )
      .all();
    const pct = (a, b) => (b === 0 ? '' : `${Math.round((a / b) * 100)}%`);
    return [
      `Series (TV, ONA and OVA works) by premiere year in data version ${version}, and how many have episode mappings for each season-based provider.`,
      '',
      '| Year | Works | TVDB mapped | TMDB mapped |',
      '| --- | --- | --- | --- |',
      ...rows.map((r) => `| ${r.year} | ${r.works} | ${r.tvdb} (${pct(r.tvdb, r.works)}) | ${r.tmdb} (${pct(r.tmdb, r.works)}) |`),
    ];
  } finally {
    db.close();
  }
}

const lines = [
  '---',
  'title: Coverage',
  'description: How much of each anime season Courmap maps, and what is waiting for review.',
  'editUrl: false',
  '---',
  '',
  '<!-- Generated by site/scripts/gen-coverage.mjs on every docs build. Do not edit. -->',
  '',
  'This page is rebuilt with the site. It doubles as a to-do list: shows awaiting review and conflicts are where help is most useful; see [how automation works](/automation/) for what each state means.',
  '',
  '## By anime season',
  '',
  ...(await seasons()),
  '',
  '## By premiere year',
  '',
  ...(await years()),
  '',
];
await writeFile(out, lines.join('\n'));
console.log(`coverage page written to ${path.relative(site, out)}`);
